/* GENERATED by scripts/build-dashboard.js from dashboard/backend/src/SlipMatch.gs.
 * Do not edit this copy; edit SlipMatch.gs and run the script again. */
/**
 * SlipMatch.gs — which employee each uploaded Payment Slip belongs to.
 *
 * The rules of scripts/format_payment_slips.py, ported unchanged:
 *   - FILENAMES ONLY. A PDF is never opened.
 *   - The name part is the filename before " - " (or before "Retail
 *     Wages"), with a store prefix removed.
 *   - A file is tied to a person only when EXACTLY ONE Staff Directory
 *     person matches, by these rules in order:
 *       1. exact Name or Payment Slip Name Alias;
 *       2. the words as a consecutive run inside the full Name;
 *       3. the name without spaces inside the full Name (5+ characters).
 *   - A filename that names a different month or year is refused.
 *   - The Store comes from the Staff Directory, never from the filename.
 *   - Nothing is ever overwritten: a target name that already exists in
 *     Drive, or that two uploads would share, is a CONFLICT.
 *
 * Pure functions with no Google services, so the same file runs in Apps
 * Script, in the Node tests, and (copied by scripts/build-dashboard.js
 * as dashboard/web/slip-match.js) in the dashboard's preview mode.
 * Edit THIS file; never the copy.
 */

var SLIP_STATUS_ = {
  ready: 'READY',            // will be saved under `target`
  pick: 'NEEDS_PICK',        // no single person matched: the admin picks one
  wrongMonth: 'WRONG_MONTH', // names another month or year: refused
  conflict: 'CONFLICT',      // the target name is taken: nothing is replaced
  duplicate: 'DUPLICATE',    // the same file was added twice
  notPdf: 'NOT_PDF'
};

var SLIP_MONTHS_ = ['january', 'february', 'march', 'april', 'may', 'june', 'july',
  'august', 'september', 'october', 'november', 'december'];

/** Removes invisible characters and normalises spaces. Visible text is never changed. */
function slipClean_(value) {
  return String(value === null || value === undefined ? '' : value)
    .replace(/[​‌‍⁠﻿]/g, '')
    .replace(/[   -   　]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/** Characters a filename cannot hold are removed, as Drive filenames already were. */
function slipFileSafe_(value) {
  return slipClean_(value).replace(/[\\\/:*?"<>|]/g, '').replace(/\s+/g, ' ').trim();
}

function slipKey_(value) {
  return slipFileSafe_(value).toLowerCase();
}

/** The standard name; must equal Payout Automation's buildSlipFileName_ (a test checks). */
function slipTargetName_(store, name, periodLabel) {
  return slipFileSafe_(store) + ' ' + slipFileSafe_(name) +
    ' - Retail Wages and Commission for ' + periodLabel + ' Payment Slip.pdf';
}

/** True when the filename names a DIFFERENT month or year than `periodLabel`. */
function slipWrongPeriod_(stem, periodLabel) {
  var low = slipClean_(stem).toLowerCase();
  var period = slipClean_(periodLabel).toLowerCase();
  if (low.indexOf(period) !== -1) { return false; }
  for (var i = 0; i < SLIP_MONTHS_.length; i++) {
    if (new RegExp('\\b' + SLIP_MONTHS_[i] + '\\b').test(low)) { return true; }
  }
  var year = period.split(' ').pop();
  var years = low.match(/\b20\d{2}\b/g) || [];
  return years.some(function (y) { return y !== year; });
}

/** The employee-name part of a filename: before " - " or "Retail Wages", minus a store prefix. */
function slipNamePart_(stem, stores) {
  var text = slipClean_(stem);
  var cut = text.indexOf(' - ');
  if (cut !== -1) {
    text = text.slice(0, cut);
  } else {
    var found = /\bretail\s+wages\b/i.exec(text);
    if (found) { text = text.slice(0, found.index); }
  }
  text = text.replace(/^[\s-]+|[\s-]+$/g, '');
  var sorted = stores.slice().sort(function (a, b) { return b.length - a.length; });
  for (var i = 0; i < sorted.length; i++) {
    var prefix = sorted[i].toLowerCase() + ' ';
    if (sorted[i] && text.toLowerCase().indexOf(prefix) === 0) {
      return text.slice(prefix.length).trim();
    }
  }
  return text;
}

function slipIsWordRun_(needle, haystack) {
  if (needle.length === 0 || needle.length > haystack.length) { return false; }
  for (var i = 0; i + needle.length <= haystack.length; i++) {
    if (needle.every(function (w, k) { return haystack[i + k] === w; })) { return true; }
  }
  return false;
}

/** { people, rule }: every person the name part could be, by the first rule that finds any. */
function slipFindPeople_(namePart, people) {
  var key = slipKey_(namePart);
  var exact = people.filter(function (p) {
    return slipKey_(p.name) === key || (p.alias && slipKey_(p.alias) === key);
  });
  if (exact.length) { return { people: exact, rule: 'exact name or alias' }; }

  var words = key.split(' ');
  var run = people.filter(function (p) { return slipIsWordRun_(words, slipKey_(p.name).split(' ')); });
  if (run.length) { return { people: run, rule: 'part of the full name' }; }

  var squashed = key.replace(/ /g, '');
  if (squashed.length >= 5) {
    var joined = people.filter(function (p) {
      return slipKey_(p.name).replace(/ /g, '').indexOf(squashed) !== -1;
    });
    if (joined.length) { return { people: joined, rule: 'full name written without spaces' }; }
  }
  return { people: [], rule: '' };
}

function slipStores_(people) {
  var seen = {};
  people.forEach(function (p) { if (p.store) { seen[p.store] = true; } });
  return Object.keys(seen);
}

/**
 * Who one filename belongs to, before any conflict check.
 * Returns { person, status, reason, rule }; `person` is null unless exactly one matched.
 */
function slipIdentify_(fileName, people, periodLabel) {
  var name = slipClean_(fileName);
  if (!/\.pdf$/i.test(name)) {
    return { person: null, status: SLIP_STATUS_.notPdf, reason: 'Only PDF files can be Payment Slips.' };
  }
  var stem = name.slice(0, -4);
  if (slipWrongPeriod_(stem, periodLabel)) {
    return { person: null, status: SLIP_STATUS_.wrongMonth,
      reason: 'This filename names a different month or year, so it is not filed under ' + periodLabel + '.' };
  }
  var part = slipNamePart_(stem, slipStores_(people));
  if (!part) {
    return { person: null, status: SLIP_STATUS_.pick, reason: 'No name could be read from the filename. Pick the person.' };
  }
  var found = slipFindPeople_(part, people);
  if (found.people.length === 0) {
    return { person: null, status: SLIP_STATUS_.pick,
      reason: 'No one in the Staff Directory matches "' + part + '". Pick the person.' };
  }
  if (found.people.length > 1) {
    return { person: null, status: SLIP_STATUS_.pick,
      reason: '"' + part + '" could be ' + found.people.map(function (p) { return p.name; }).sort().join(' or ') +
        '. Pick the right person.' };
  }
  return { person: found.people[0], status: SLIP_STATUS_.ready, reason: 'Matched by ' + found.rule + '.', rule: found.rule };
}

/**
 * The plan for one upload batch. Changes nothing.
 *
 *   input.period    'October 2026'
 *   input.people    Staff Directory: [{ id, name, alias, store }]
 *   input.existing  filenames already in the month's Payment Slip folder
 *   input.files     [{ key, name, size, pickedId }] — pickedId is the admin's choice
 *
 * Returns rows in the order of input.files:
 *   { key, name, status, reason, employeeId, employeeName, store, target, picked, rename }
 */
function slipPlanUpload_(input) {
  var people = input.people || [];
  var byId = {};
  people.forEach(function (p) { byId[p.id] = p; });
  var existing = {};
  (input.existing || []).forEach(function (n) { existing[slipKey_(n)] = n; });
  var seenFiles = {};
  var claimed = {};

  return (input.files || []).map(function (file) {
    var row = { key: file.key, name: file.name, status: '', reason: '', employeeId: '', employeeName: '',
      store: '', target: '', picked: false, rename: false };
    var same = slipKey_(file.name) + '|' + (file.size || 0);
    if (seenFiles[same]) {
      row.status = SLIP_STATUS_.duplicate;
      row.reason = 'The same file was added twice. Only the first one is used.';
      return row;
    }
    seenFiles[same] = true;

    var id = slipIdentify_(file.name, people, input.period);
    var person = id.person;
    if (file.pickedId && id.status !== SLIP_STATUS_.notPdf && id.status !== SLIP_STATUS_.wrongMonth) {
      person = byId[file.pickedId] || null;
      if (!person) {
        row.status = SLIP_STATUS_.pick;
        row.reason = 'The person you picked is no longer in the Staff Directory. Pick again.';
        return row;
      }
      row.picked = true;
      id = { status: SLIP_STATUS_.ready, reason: 'You picked this person.' };
    }
    row.status = id.status;
    row.reason = id.reason;
    if (!person) { return row; }

    row.employeeId = person.id;
    row.employeeName = person.name;
    row.store = person.store || '';
    if (!person.store) {
      row.status = SLIP_STATUS_.pick;
      row.reason = person.name + ' has no Store in the Staff Directory, so the filename cannot be built.';
      return row;
    }
    row.target = slipTargetName_(person.store, person.name, input.period);
    row.rename = row.target !== slipClean_(file.name);
    var key = slipKey_(row.target);
    if (existing[key]) {
      row.status = SLIP_STATUS_.conflict;
      row.reason = person.name + ' already has this slip in Drive. Nothing is replaced.';
    } else if (claimed[key]) {
      row.status = SLIP_STATUS_.conflict;
      row.reason = 'Another file ("' + claimed[key] + '") is also for ' + person.name + '. Remove one.';
    } else {
      claimed[key] = file.name;
    }
    return row;
  });
}

/**
 * The payroll people with no slip yet: none in Drive for this month, and
 * none READY in `rows`. A Drive file counts only when it identifies
 * exactly that person by the same rules.
 *
 *   payroll   [{ id, name, store }] — this month's people
 *   people    the whole Staff Directory (for matching)
 */
function slipMissingPeople_(payroll, people, existing, rows, periodLabel) {
  var has = {};
  (existing || []).forEach(function (n) {
    var id = slipIdentify_(n, people, periodLabel);
    if (id.person && id.status === SLIP_STATUS_.ready) { has[id.person.id] = 'drive'; }
  });
  (rows || []).forEach(function (r) {
    if (r.status === SLIP_STATUS_.ready && r.employeeId && !has[r.employeeId]) { has[r.employeeId] = 'upload'; }
  });
  return payroll.filter(function (p) { return !has[p.id]; });
}

/**
 * The slips ALREADY in the month's folder: who each one is for, and the
 * standard name it would get (owner, 2026-10-27: view every slip, and
 * rename them to the standard name). Changes nothing.
 *
 *   input.period  'October 2026'
 *   input.people  Staff Directory: [{ id, name, alias, store }]
 *   input.files   [{ name, url, fileId }] in the folder now
 *   input.held    Employee IDs whose payout is Sent or Review Required
 *   input.picks   optional { fileId: employeeId } chosen by the admin
 *
 * Returns rows: { fileId, name, url, state, reason, employeeId, employeeName, target }
 *   state: 'standard' (already right) · 'rename' (will get `target`) ·
 *          'unknown' (no single person; pick one) · 'blocked' (cannot be renamed; see reason)
 */
function slipPlanRenames_(input) {
  var people = input.people || [];
  var byId = {};
  people.forEach(function (p) { byId[p.id] = p; });
  var held = {};
  (input.held || []).forEach(function (id) { held[id] = true; });
  var taken = {};
  (input.files || []).forEach(function (f) { taken[slipKey_(f.name)] = f.fileId; });
  var picks = input.picks || {};

  return (input.files || []).map(function (f) {
    var row = { fileId: f.fileId, name: f.name, url: f.url, state: '', reason: '', employeeId: '', employeeName: '', target: '' };
    var id = slipIdentify_(f.name, people, input.period);
    var person = id.person;
    if (picks[f.fileId] && id.status !== SLIP_STATUS_.notPdf && id.status !== SLIP_STATUS_.wrongMonth) {
      person = byId[picks[f.fileId]] || null;
    }
    if (!person) {
      row.state = id.status === SLIP_STATUS_.pick ? 'unknown' : 'blocked';
      row.reason = id.reason;
      return row;
    }
    row.employeeId = person.id;
    row.employeeName = person.name;
    if (!person.store) { row.state = 'blocked'; row.reason = person.name + ' has no Store in the Staff Directory.'; return row; }
    row.target = slipTargetName_(person.store, person.name, input.period);
    if (slipClean_(f.name) === row.target) { row.state = 'standard'; row.reason = 'Already the standard name.'; return row; }
    if (held[person.id]) { row.state = 'blocked'; row.reason = person.name + ' was already sent, so the slip is left as it is.'; return row; }
    var owner = taken[slipKey_(row.target)];
    if (owner && owner !== f.fileId) { row.state = 'blocked'; row.reason = 'Another file already has the standard name for ' + person.name + '.'; return row; }
    taken[slipKey_(row.target)] = f.fileId;
    row.state = 'rename';
    row.reason = picks[f.fileId] ? 'You picked this person.' : id.reason;
    return row;
  });
}
